// Формируем меню с inline-кнопками
const chatId = msg.payload.chatId;

msg.payload = {
    chatId: chatId,
    type: "message",
    content: "🎵 Какой у тебя любимый жанр музыки?\n\nВыбери один из вариантов ниже:",
    options: {
        reply_markup: {
            inline_keyboard: [
                [
                    { text: "🎸 Рок", callback_data: "genre_rock" },
                    { text: "🎤 Поп", callback_data: "genre_pop" }
                ],
                [
                    { text: "🎻 Классика", callback_data: "genre_classic" },
                    { text: "🎧 Электроника", callback_data: "genre_electro" }
                ]
            ]
        }
    }
};

return msg;

// Получаем данные из callback_query
const chatId = msg.payload.chatId;
const callbackData = msg.payload.content;  // то, что лежит в callback_data кнопки

// Словарь жанров
const genres = {
    "genre_rock": "🎸 Рок",
    "genre_pop": "🎤 Поп",
    "genre_classic": "🎻 Классика",
    "genre_electro": "🎧 Электроника"
};

// === Сценарий 1: пользователь нажал кнопку жанра ===
if (genres[callbackData]) {
    const genreName = genres[callbackData];
    msg.payload = {
        chatId: chatId,
        type: "message",
        content: `Твой выбор: ${genreName}\n\nОтличный вкус! 🎵`,
        options: {
            reply_markup: {
                inline_keyboard: [
                    [
                        { text: "↩ Вернуться в меню", callback_data: "back_to_menu" }
                    ]
                ]
            }
        }
    };
    return msg;
}

// === Сценарий 2: пользователь нажал "Вернуться в меню" ===
if (callbackData === "back_to_menu") {
    msg.payload = {
        chatId: chatId,
        type: "message",
        content: "🎵 Какой у тебя любимый жанр музыки?\n\nВыбери один из вариантов ниже:",
        options: {
            reply_markup: {
                inline_keyboard: [
                    [
                        { text: "🎸 Рок", callback_data: "genre_rock" },
                        { text: "🎤 Поп", callback_data: "genre_pop" }
                    ],
                    [
                        { text: "🎻 Классика", callback_data: "genre_classic" },
                        { text: "🎧 Электроника", callback_data: "genre_electro" }
                    ]
                ]
            }
        }
    };
    return msg;
}

// === Сценарий 3: неизвестная callback-команда ===
msg.payload = {
    chatId: chatId,
    type: "message",
    content: "Не понял команду. Попробуй /music заново."
};
return msg;
